function RW = get_runways(icao)
%GET_RUNWAYS Runway outlines as centrelines (lat, lon) plus width (m): a struct array with fields lat, lon, width, name.
%   Source: OpenStreetMap contributors (ODbL), queried via the Overpass API on 2026-11-09. The numbers were relayed by
%   a web-fetch tool, so they were checked: each computed runway length plus its displaced threshold agrees with the
%   tagged length to within about 2.5%. Only airports whose data was retrieved are listed.
RW = struct('lat',{},'lon',{},'width',{},'name',{});
switch upper(icao)
    case 'EGGD'      % Bristol: runway 09/27, 2011 m x 45 m (+ displaced-threshold surface at the east end)
        RW(1).lat = [51.3831542 51.3831303 51.3831118 51.3830880 51.3830816 51.3828763 51.3828688 51.3828507 51.3828305 51.3825301 51.3824967 51.3821517 51.3821115]';
        RW(1).lon = [-2.7064994 -2.7071187 -2.7075986 -2.7082183 -2.7083841 -2.7137086 -2.7139027 -2.7143720 -2.7148977 -2.7226910 -2.7235552 -2.7325061 -2.7335486]';
        RW(1).width = 45; RW(1).name = '09/27';
        RW(2).lat = [51.3832261 51.3831953 51.3831542]'; RW(2).lon = [-2.7046871 -2.7053747 -2.7064994]';
        RW(2).width = 45; RW(2).name = '';
    case 'EHAM'      % Amsterdam Schiphol: six runways (tagged lengths in m) and their displaced thresholds
        RW = addRW(RW,'18L/36R Aalsmeerbaan 3400', 45, [52.3161396 4.7796905; 52.3159917 4.7796768; 52.3154029 4.7796220; 52.3135526 4.7794501; 52.3130768 4.7794059; 52.3124638 4.7793490; 52.3076311 4.7789000; 52.3045196 4.7786109; 52.3030223 4.7784718; 52.3011619 4.7783055; 52.3001990 4.7782123; 52.2968705 4.7779004; 52.2962235 4.7778443; 52.2913173 4.7773847; 52.2908837 4.7773444]);
        RW = addRW(RW,'04/22 Oostbaan 2014', 45, [52.3004269 4.7835659; 52.3012321 4.7847177; 52.3014324 4.7850042; 52.3050752 4.7902154; 52.3052309 4.7904381; 52.3054693 4.7907792; 52.3089690 4.7957861; 52.3091149 4.7959949; 52.3092548 4.7961950; 52.3116505 4.7996227; 52.3118924 4.7999689; 52.3137588 4.8026395; 52.3140187 4.8030113]);
        RW = addRW(RW,'18C/36C Zwanenburgbaan 3300', 45, [52.3313959 4.7400348; 52.3306946 4.7399703; 52.3282696 4.7397471; 52.3238454 4.7393400; 52.3226177 4.7392271; 52.3211090 4.7390883; 52.3204322 4.7390260; 52.3194275 4.7389335; 52.3184341 4.7388422; 52.3164736 4.7386618; 52.3135420 4.7383921; 52.3087105 4.7379476; 52.3058222 4.7376820]);
        RW = addRW(RW,'09/27 Buitenveldertbaan 3453', 45, [52.3166887 4.7477162; 52.3167550 4.7496588; 52.3172493 4.7641344; 52.3173231 4.7662937; 52.3174046 4.7686810; 52.3176857 4.7769143; 52.3177378 4.7784393; 52.3177554 4.7789545; 52.3177856 4.7798401; 52.3179094 4.7834655; 52.3183331 4.7958720; 52.3183687 4.7969159]);
        RW = addRW(RW,'18R/36L Polderbaan 3800', 60, [52.3285791 4.7088354; 52.3290639 4.7088796; 52.3342463 4.7093521; 52.3348130 4.7094037; 52.3367787 4.7095829; 52.3402080 4.7098956; 52.3434450 4.7101908; 52.3455267 4.7103833; 52.3571457 4.7114402; 52.3602501 4.7117234]);
        RW = addRW(RW,'06/24 Kaagbaan 3500', 45, [52.2891167 4.7372484; 52.2917820 4.7441860; 52.2920230 4.7448134; 52.2923230 4.7455944; 52.2923975 4.7457883; 52.2925463 4.7461757; 52.2951463 4.7529440; 52.2952681 4.7532611; 52.2956333 4.7542117; 52.2961231 4.7554869; 52.2964544 4.7563494; 52.2975792 4.7592775; 52.2992961 4.7637475; 52.3005826 4.7670969; 52.3010569 4.7683318; 52.3023041 4.7715792; 52.3030264 4.7734598; 52.3038977 4.7757284; 52.3039640 4.7759011; 52.3041303 4.7763341; 52.3043755 4.7769727]);
        % displaced thresholds
        RW = addRW(RW,'Kaagbaan displaced threshold', 45, [52.2879516 4.7342206; 52.2881141 4.7346427; 52.2886317 4.7359880; 52.2891167 4.7372484]);
        RW = addRW(RW,'Buitenveldertbaan displaced threshold', 45, [52.3166413 4.7462194; 52.3166520 4.7466552; 52.3166768 4.7473663; 52.3166887 4.7477162]);
        RW = addRW(RW,'Aalsmeerbaan displaced threshold', 45, [52.3213300 4.7801622; 52.3211150 4.7801427; 52.3208711 4.7801232; 52.3177856 4.7798401; 52.3163443 4.7797091; 52.3161396 4.7796905]);
        RW = addRW(RW,'Zwanenburgbaan displaced threshold', 45, [52.3017775 4.7373180; 52.3023357 4.7373682; 52.3041307 4.7375298; 52.3046275 4.7375745; 52.3058222 4.7376820]);
        RW = addRW(RW,'Polderbaan displaced threshold', 60, [52.3626695 4.7119456; 52.3624351 4.7119241; 52.3615294 4.7118409; 52.3602501 4.7117234]);
    otherwise
        % other airports: no data stored
end
end

function RW = addRW(RW, name, width, latlon)
k = numel(RW) + 1;
RW(k).lat = latlon(:,1); RW(k).lon = latlon(:,2); RW(k).width = width; RW(k).name = name;
end
